package com.wandertrace.service;
import com.wandertrace.dto.ContentDtos.*;import com.wandertrace.exception.*;import com.wandertrace.storage.MediaStorageService;import java.io.*;import java.nio.file.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
@Service public class MediaService {private final JdbcTemplate db;private final TripAccessService access;private final ContentAccessService content;private final MediaStorageService storage;private final Map<String,Long> limits;public MediaService(JdbcTemplate db,TripAccessService a,ContentAccessService c,MediaStorageService s,@Value("${wandertrace.uploads.image-max-size}")org.springframework.util.unit.DataSize image,@Value("${wandertrace.uploads.video-max-size}")org.springframework.util.unit.DataSize video,@Value("${wandertrace.uploads.audio-max-size}")org.springframework.util.unit.DataSize audio){this.db=db;access=a;content=c;storage=s;limits=Map.of("IMAGE",image.toBytes(),"VIDEO",video.toBytes(),"AUDIO",audio.toBytes());}public List<Media>list(UUID user,UUID memory){access.requireView(user,content.tripForMemory(memory));return db.queryForList("select * from media where memory_id=? order by sort_order",memory).stream().map(this::map).toList();}@Transactional public Media upload(UUID user,UUID memory,MultipartFile file,String title,String caption,Integer order)throws IOException{access.requireEdit(user,content.tripForMemory(memory));String type=type(file);if(file.isEmpty())throw new IllegalArgumentException("File is empty");if(file.getSize()>limits.get(type))throw new MaxUploadExceededException();String ext=extension(file.getOriginalFilename());String key="memories/"+memory+"/"+UUID.randomUUID()+"."+ext;var stored=storage.upload(key,file.getInputStream(),file.getSize(),file.getContentType());UUID id=UUID.randomUUID();db.update("insert into media(id,memory_id,type,storage_key,url,title,caption,mime_type,file_size,sort_order)values(?,?,?,?,?,?,?,?,?,?)",id,memory,type,stored.key(),stored.url(),title,caption,file.getContentType(),file.getSize(),order==null?0:order);return get(user,id);}@Transactional public Media update(UUID user,UUID id,MediaMetadata r){UUID memory=content.memoryForMedia(id);access.requireEdit(user,content.tripForMemory(memory));if(Boolean.TRUE.equals(r.cover()))db.update("update memories set cover_media_id=? where id=?",id,memory);db.update("update media set title=coalesce(?,title),caption=coalesce(?,caption),sort_order=coalesce(?,sort_order) where id=?",r.title(),r.caption(),r.sortOrder(),id);return get(user,id);}@Transactional public void delete(UUID user,UUID id)throws IOException{UUID memory=content.memoryForMedia(id);access.requireEdit(user,content.tripForMemory(memory));var row=one(id);db.update("update memories set cover_media_id=null where cover_media_id=?",id);db.update("delete from media where id=?",id);storage.delete((String)row.get("storage_key"));}public Media get(UUID user,UUID id){UUID memory=content.memoryForMedia(id);access.requireView(user,content.tripForMemory(memory));return map(one(id));}private String type(MultipartFile f){String mime=Optional.ofNullable(f.getContentType()).orElse("").toLowerCase();String ext=extension(f.getOriginalFilename());if(Set.of("jpg","jpeg","png","webp","heic","heif").contains(ext)&&Set.of("image/jpeg","image/png","image/webp","image/heic","image/heif").contains(mime))return "IMAGE";if(Set.of("mp4","mov").contains(ext)&&Set.of("video/mp4","video/quicktime").contains(mime))return "VIDEO";if(Set.of("mp3","m4a","wav").contains(ext)&&Set.of("audio/mpeg","audio/mp4","audio/wav","audio/x-m4a").contains(mime))return "AUDIO";throw new IllegalArgumentException("Unsupported media type");}private String extension(String name){String n=Optional.ofNullable(name).orElse("");if(n.contains("/")||n.contains("\\"))throw new IllegalArgumentException("Unsafe filename");int dot=n.lastIndexOf('.');if(dot<1||dot==n.length()-1)throw new IllegalArgumentException("File extension required");return n.substring(dot+1).toLowerCase(Locale.ROOT);}private Map<String,Object>one(UUID id){var rows=db.queryForList("select * from media where id=?",id);if(rows.isEmpty())throw new NotFoundException("Media not found");return rows.getFirst();}private Media map(Map<String,Object>r){return new Media((UUID)r.get("id"),(UUID)r.get("memory_id"),(String)r.get("type"),(String)r.get("storage_key"),(String)r.get("url"),(String)r.get("thumbnail_url"),(String)r.get("title"),(String)r.get("caption"),(String)r.get("mime_type"),((Number)r.get("file_size")).longValue(),((Number)r.get("sort_order")).intValue(),((java.sql.Timestamp)r.get("created_at")).toInstant());}}
